from httpie.plugins.registry import plugin_manager

class _UpperFormatter:
    def __init__(self, env=None, **kwargs):
        self.enabled = True

    def format_headers(self, headers):
        return headers.upper()

class _DisabledFormatter:
    def __init__(self, env=None, **kwargs):
        self.enabled = False

    def format_headers(self, headers):
        return "DISABLED"

class _SuffixFormatter:
    def __init__(self, env=None, **kwargs):
        self.enabled = True

    def format_headers(self, headers):
        return headers + "\nX-Test: yes"

grouped = {"headers": [_UpperFormatter, _DisabledFormatter, _SuffixFormatter]}
with patch.object(plugin_manager, "get_formatters_grouped", return_value=grouped):
    formatter = Formatting(groups=["headers"])
    result = formatter.format_headers("content-type: text/plain")

assert len(formatter.enabled_plugins) == 2
assert result == "CONTENT-TYPE: TEXT/PLAIN\nX-Test: yes"

