import pytest

from httpie.plugins.registry import plugin_manager

# change to wherever Conversion actually lives
from httpie_conversion import Conversion


class JsonConverter:
    def __init__(self, mime):
        self.mime = mime

    @classmethod
    def supports(cls, mime):
        return mime == "application/json"


class NeverConverter:
    def __init__(self, mime):
        self.mime = mime

    @classmethod
    def supports(cls, mime):
        return False


def test_returns_matching_converter_instance(monkeypatch):
    monkeypatch.setattr(plugin_manager, "get_converters", lambda: [JsonConverter])

    converter = Conversion.get_converter("application/json")

    assert isinstance(converter, JsonConverter)
    assert converter.mime == "application/json"


def test_returns_none_when_no_converter_supports_mime(monkeypatch):
    monkeypatch.setattr(plugin_manager, "get_converters", lambda: [JsonConverter])

    assert Conversion.get_converter("text/csv") is None


def test_skips_converters_that_do_not_support_mime(monkeypatch):
    monkeypatch.setattr(
        plugin_manager, "get_converters", lambda: [NeverConverter, JsonConverter]
    )

    converter = Conversion.get_converter("application/json")

    assert isinstance(converter, JsonConverter)


def test_first_matching_converter_wins(monkeypatch):
    class SecondJsonConverter(JsonConverter):
        pass

    monkeypatch.setattr(
        plugin_manager, "get_converters", lambda: [JsonConverter, SecondJsonConverter]
    )

    converter = Conversion.get_converter("application/json")

    assert type(converter) is JsonConverter


@pytest.mark.parametrize(
    "mime", [None, "", "json", "application/", "/json", "a/b/c", "a b/c"]
)
def test_invalid_mime_returns_none_without_touching_plugins(monkeypatch, mime):
    def boom():
        raise AssertionError("get_converters() must not be called for invalid mime")

    monkeypatch.setattr(plugin_manager, "get_converters", boom)

    assert Conversion.get_converter(mime) is None
